css='''*{box-sizing:border-box}body{margin:0;background:#f6f4ee;color:#26332d;font-family:"Noto Sans CJK TC",sans-serif;font-size:18px;line-height:1.95}aside{position:fixed;width:280px;inset:0 auto 0 0;padding:30px 20px;background:#e9eee4;overflow:auto;border-right:1px solid #d7dfd0}aside h1{font-size:22px;line-height:1.5}button{font:inherit;cursor:pointer;border:1px solid #cbd4c4;background:#fffdf7;color:#2c4234;border-radius:7px;padding:9px 14px}aside button{display:block;width:100%;text-align:left;font-size:15px;margin:9px 0;line-height:1.7}aside button.active{background:#284f3a;color:white}main{margin-left:280px;padding:40px 60px 100px;max-width:1260px}header{border-bottom:1px solid #d6dcca;margin-bottom:28px;padding-bottom:20px}.kicker{color:#6f8067;font-size:14px;letter-spacing:.13em}header h1{font-size:30px;line-height:1.5}.page{max-width:800px}.page h2{font-size:29px;line-height:1.6;margin:20px 0 28px;color:#244a35}.page h3{font-size:21px;line-height:1.7;margin:40px 0 14px;padding-left:13px;border-left:4px solid #8b9f6c}.page p{margin:16px 0 23px}.page strong{color:#2c603e}.page table{width:100%;border-collapse:collapse;font-size:16px;background:#fffdf8;margin:24px 0;line-height:1.8}.page th{background:#e7edde;text-align:left}.page td,.page th{padding:12px 14px;border:1px solid #d5ddce;vertical-align:top}.page ul,.page ol{padding-left:26px}.page li{margin:12px 0}.page a{color:#2a6d4a;overflow-wrap:anywhere}footer{position:fixed;bottom:0;right:0;left:280px;padding:13px 40px;background:#fffdf6f2;border-top:1px solid #d5ddce;display:flex;align-items:center;gap:14px}.hidden{display:none}#counter{margin-left:auto;font-size:14px;color:#6e7c65}.print{font-size:14px}.note{font-size:15px;color:#65745e}body.all .page{padding-bottom:35px;border-bottom:2px solid #cdd7c2}@media(max-width:900px){aside{position:static;width:auto;padding:15px}aside h1{font-size:20px}aside nav{display:flex;overflow:auto}aside button{min-width:185px;margin-right:8px}main{margin:0;padding:20px 20px 100px}header h1{font-size:25px}.page h2{font-size:24px}.page table{font-size:14px;display:block;overflow:auto}footer{left:0;padding:10px 14px}body{font-size:17px}}@media print{aside,footer,header{display:none}main{margin:0;padding:0;max-width:none}.page{display:block!important;max-width:none;break-before:page}.page:first-of-type{break-before:auto}body{background:white;font-size:11pt;line-height:1.8}.page h2{font-size:18pt}.page h3{font-size:13pt;break-after:avoid}.page table{font-size:10pt}tr{break-inside:avoid}p{orphans:3;widows:3}}'''
js='''let index=0;const pages=[...document.querySelectorAll('.page')],buttons=[...document.querySelectorAll('nav button')];function show(i){index=Math.max(0,Math.min(pages.length-1,i));document.body.classList.remove('all');pages.forEach((p,k)=>p.classList.toggle('hidden',k!==index));buttons.forEach((b,k)=>b.classList.toggle('active',k===index));document.getElementById('counter').textContent=(index+1)+' / '+pages.length;document.getElementById('prev').disabled=index===0;document.getElementById('next').disabled=index===pages.length-1;window.scrollTo(0,0)}buttons.forEach(b=>b.onclick=()=>show(Number(b.dataset.i)));document.getElementById('prev').onclick=()=>show(index-1);document.getElementById('next').onclick=()=>show(index+1);document.getElementById('all').onclick=()=>{document.body.classList.add('all');pages.forEach(p=>p.classList.remove('hidden'));document.getElementById('counter').textContent='全文閱讀';window.scrollTo(0,0)};show(0);'''
doc=f'''<!doctype html><html lang="zh-Hant"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>111 年果樹學｜教學詳解修訂樣本</title><style>{css}</style><aside><div class="kicker">詳細修訂版 · 樣本</div><h1>111 年果樹學</h1><p class="note">七道大題 · 100 分<br>先理解，再練習申論</p><nav>{''.join(nav)}</nav><button id="all">全文閱讀</button><button onclick="window.print()">列印整份詳解</button><p class="note">配分細項是建議作答架構，非校方評分細則。</p></aside><main><header><div class="kicker">原題 → 直接答案 → 因果解析 → 實例 → 申論稿</div><h1>每題分開讀，把原理講清楚。</h1><p class="note">重寫樣本，2026 年 10 月 23 日。保留原題配分與小題，移除舊版重複通用段落。</p></header>{''.join(pages)}</main><footer><button id="prev">← 上一題</button><button id="next">下一題 →</button><span id="counter"></span></footer><script>{js}</script></html>'''
(root/'111年果樹學_逐題教學詳解.html').write_text(doc)
